mapper.select:
SELECT bmt10_info_id AS info_id , bmt10_ast_class_tree_id AS ast_class_tree_id , ast01_class_tree_nm AS ast_class_tree_name , bmt10_apply_date::date AS apply_date , bmt10_retire_date::date AS retire_date , bmt10_acq_amount AS acq_amount , bmt10_acq_info AS acq_info , bmt10_spec AS spec , bmt10_note AS note , COALESCE(f_emp_kor_nm(( SELECT bmt11_person_id FROM bmt11_history WHERE bmt11_info_id = bmt10_info_id AND bmt11_start_date <= #{baseDate} ORDER BY bmt11_start_date DESC LIMIT 1 )), '') AS person_name FROM bmt10_info INNER JOIN ast01_class_tree ON ast01_class_tree_id = bmt10_ast_class_tree_id WHERE 1=1 AND bmt10_company_id = #{companyId} AND ast01_item_s_class_cd LIKE #{itemClassCode}
AND #{baseDate} <= COALESCE(bmt10_retire_date, to_date('99991231','yyyyMMdd'))
AND CONCAT(ast01_class_tree_nm, bmt10_acq_info, bmt10_spec, bmt10_note) ILIKE #{searchText} ORDER BY bmt10_apply_date DESC, bmt10_retire_date DESC, bmt10_acq_amount DESC

mapper.update:
UPDATE bmt10_info
   SET bmt10_ast_class_tree_id = #{req.astClassTreeId}
     , bmt10_apply_date        = #{req.applyDate}
     , bmt10_retire_date       = #{req.retireDate}
     , bmt10_acq_amount        = #{req.acqAmount}
     , bmt10_acq_info          = #{req.acqInfo}
     , bmt10_spec              = #{req.spec}
     , bmt10_note              = #{req.note}
 WHERE bmt10_info_id    = #{infoId}
   AND bmt10_company_id = #{companyId}

mapper.delete:
DELETE FROM bmt10_info
 WHERE bmt10_info_id    = #{infoId}
   AND bmt10_company_id = #{companyId}
